const pass=window.localStorage.getItem("pass");function enviarPass(){document.getElementById("enviar").removeEventListener("click",enviarPass);let e=document.getElementById("pass").value;window.localStorage.setItem("pass",e),location.reload()}pass?(document.getElementById("pagina-menu-container").style.display="flex",document.getElementById("pagina-login-container").style.display="none"):(document.getElementById("pagina-login-container").style.display="flex",document.getElementById("pagina-menu-container").style.display="none",document.getElementById("enviar").addEventListener("click",enviarPass));